/// One input's declared dimension, or `None` where the id is unknown or the input
/// carries no unit.
///
/// `None` is a refusal rather than an absence: a coefficient attached to an input that
/// is not a quantity is a value the format cannot supply, so the caller's job is to
/// name the entry rather than to proceed without a check.
#[must_use]
pub fn input_dimension(spec: &str, name: &str) -> Option<&'static str> {
    SPEC_INPUT_DIMENSIONS
        .iter()
        .find(|(id, input, _)| *id == spec && *input == name)
        .map(|(_, _, dimension)| *dimension)
}
